tokenizer_config.chat_template:
{# Handle optional system message #}
{%- if messages and messages[0]["role"] == "system" -%}
  {%- set system_message = messages[0]["content"] -%}
  {%- set loop_messages = messages[1:] -%}
{%- else -%}
  {%- set system_message = none -%}
  {%- set loop_messages = messages -%}
{%- endif -%}

{# Ensure tools is defined #}
{%- if not tools is defined -%}
  {%- set tools = none -%}
{%- endif -%}

{# Collect user messages #}
{%- set user_messages = loop_messages
  | selectattr("role", "equalto", "user")
  | list
-%}

{# Validate alternating user/assistant roles (disabled)
{%- set ns = namespace(index=0) -%}
{%- for message in loop_messages -%}
  {%- if not (
    message.role in ["tool", "tool_results"]
    or (message.tool_calls is defined and message.tool_calls)
  ) -%}
    {%- if (message["role"] == "user") != (ns.index is even) -%}
      {{- raise_exception(
        "After the optional system message, conversation roles must alternate "
        ~ "user/assistant/user/assistant/..."
      ) -}}
    {%- endif -%}
    {%- set ns.index = ns.index + 1 -%}
  {%- endif -%}
{%- endfor -%}
#}

{{- bos_token -}}

{# Process messages #}
{%- for message in loop_messages -%}
  {%- set role = message["role"] -%}

  {# User message #}
  {%- if role == "user" -%}
    {%- set is_last_user = message == user_messages[-1] -%}

    {%- if is_last_user -%}
      {%- set user_content = message["content"] -%}

      {%- if system_message -%}
        {%- if tools is not none -%}
          <instruction>{{ system_message }}

<list_tools>[
{%- for tool in tools -%}
  {{ tool | tojson }}{%- if not loop.last -%}, {% endif -%}
{%- endfor -%}
]</list_tools>

{{ user_content }}</instruction>
        {%- else -%}
          <instruction>{{ system_message }}

{{ user_content }}</instruction>
        {%- endif -%}
      {%- else -%}
        <instruction>{{ user_content }}</instruction>
      {%- endif -%}
    {%- else -%}
      <instruction>{{ message["content"] }}</instruction>
    {%- endif -%}

  {# Tool calls #}
  {%- elif message.tool_calls is defined and message.tool_calls -%}
    <tool_call>[
    {%- for tool_call in message.tool_calls -%}
      {{ tool_call | tojson }}{%- if not loop.last -%}, {% endif -%}
    {%- endfor -%}
    ]</tool_call>{{- eos_token -}}

  {# Assistant response #}
  {%- elif role == "assistant" -%}
    {{ message["content"] }}{{- eos_token -}}

  {# Tool result #}
  {%- elif role in ["tool", "tool_results"] -%}
    {%- if message.content is defined and message.content.content is defined -%}
      {%- set content = message.content.content -%}
    {%- else -%}
      {%- set content = message.content -%}
    {%- endif -%}

    <tool_result>{{ content }}</tool_result>
  {# Invalid role #}
  {%- else -%}
    {{- raise_exception(
      "Only user and assistant roles are supported, "
      ~ "with the exception of an initial optional system message!"
    ) -}}
  {%- endif -%}
{%- endfor -%}

config.chat_template_jinja:
{# Handle optional system message #}
{%- if messages and messages[0]["role"] == "system" -%}
  {%- set system_message = messages[0]["content"] -%}
  {%- set loop_messages = messages[1:] -%}
{%- else -%}
  {%- set system_message = "You are Velvet-2-3B, a Large Language Model (LLM) created by Almawave Labs, an Italian company headquartered in Rome.
You are an helpful assistant. Your goal is to provide clear, accurate, and useful and polite answers to the user.
Do not fabricate facts, names, dates, numbers, references, explanations, or reasoning steps. If the available information is insufficient, state the limitation and ask for additional information when necessary." %}
  {%- set loop_messages = messages -%}
{%- endif -%}

{# Ensure tools is defined #}
{%- if not tools is defined -%}
  {%- set tools = none -%}
{%- endif -%}

{# Collect user messages #}
{%- set user_messages = loop_messages
  | selectattr("role", "equalto", "user")
  | list
-%}

{{- bos_token -}}

{# Process messages #}
{%- for message in loop_messages -%}
  {%- set role = message["role"] -%}

  {# User message #}
  {%- if role == "user" -%}
    {%- set is_last_user = message == user_messages[-1] -%}

    {%- if is_last_user -%}
      {%- set user_content = message["content"] -%}

      {%- if system_message -%}
        {%- if tools is not none -%}
          <instruction>{{ system_message }}

<list_tools>[
{%- for tool in tools -%}
  {{ tool["function"] | tojson }}{%- if not loop.last -%}, {% endif -%}
{%- endfor -%}
]</list_tools>

{{ user_content }}</instruction>
        {%- else -%}
          <instruction>{{ system_message }}

{{ user_content }}</instruction>
        {%- endif -%}
      {%- else -%}
        <instruction>{{ user_content }}</instruction>
      {%- endif -%}
    {%- else -%}
      <instruction>{{ message["content"] }}</instruction>
    {%- endif -%}

  {# Tool calls #}
  {%- elif message.tool_calls is defined and message.tool_calls -%}
    <tool_call>[
    {%- for tool_call in message.tool_calls -%}
      {#- vLLM passes arguments as a dict; OpenAI clients send a JSON string -#}
      {%- set arguments = tool_call["function"]["arguments"] -%}
      {"name": {{ tool_call["function"]["name"] | tojson }}, "arguments": {{ arguments | tojson if arguments is mapping else arguments }}}{%- if not loop.last -%}, {% endif -%}
    {%- endfor -%}
    ]</tool_call>{{- eos_token -}}

  {# Assistant response #}
  {%- elif role == "assistant" -%}
    {{ message["content"] }}{{- eos_token -}}

  {# Tool result #}
  {%- elif role in ["tool", "tool_results"] -%}
    {%- if message.content is defined and message.content.content is defined -%}
      {%- set content = message.content.content -%}
    {%- else -%}
      {%- set content = message.content -%}
    {%- endif -%}

    {#- The native template emits a newline after each tool result -#}
    <tool_result>{{ content }}</tool_result>{{ "\n" }}
  {%- else -%}
    {{- raise_exception(
      "Only user and assistant roles are supported, "
      ~ "with the exception of an initial optional system message!"
    ) -}}
  {%- endif -%}
{%- endfor -%}
